// src/App.js - Flujo por páginas: Login → Registrar → Configurar → Dashboard
import React, { useState, useEffect } from 'react';
import {
  Card,
  Typography,
  Grid,
  Slider,
  Button,
  Alert,
  CircularProgress,
  Box,
  Divider,
  TextField,
  InputAdornment,
  Container,
  LinearProgress,
  Chip
} from '@mui/material';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  CartesianGrid,
  XAxis,
  YAxis,
  Tooltip as RechartsTooltip
} from 'recharts';
import { useAuth } from './context/AuthContext';
import Auth from './components/Auth';
import axios from 'axios';

const API_URL = 'https://backend-control-tanque-production-154a.up.railway.app';

const COLORS = {
  primary: '#2563eb',
  success: '#10b981',
  warning: '#f59e0b',
  danger: '#ef4444',
  dark: '#1f2937',
  light: '#f3f4f6'
};

function App() {
  const { user, logout, isAuthenticated, loading } = useAuth();
  const [devices, setDevices] = useState([]);
  const [selectedDevice, setSelectedDevice] = useState(null);
  const [history, setHistory] = useState([]);
  const [alert, setAlert] = useState(null);
  const [currentStep, setCurrentStep] = useState(1); // 1=registrar, 2=configurar, 3=dashboard
  
  // Registrar dispositivo
  const [newDeviceId, setNewDeviceId] = useState('');
  const [newDeviceName, setNewDeviceName] = useState('');
  
  // Configurar tanque
  const [tankHeight, setTankHeight] = useState('');
  const [minLevel, setMinLevel] = useState('');
  const [maxLevel, setMaxLevel] = useState('');

  useEffect(() => {
    if (isAuthenticated) {
      fetchDevices();
    }
  }, [isAuthenticated]);

  useEffect(() => {
    if (selectedDevice && isAuthenticated) {
      fetchDeviceStatus(selectedDevice.deviceId);
      fetchDeviceHistory(selectedDevice.deviceId);
      // Determinar el paso actual
      if (!selectedDevice.tankHeight || selectedDevice.tankHeight === 100 && !selectedDevice.minLevel && !selectedDevice.maxLevel) {
        setCurrentStep(2); // Necesita configuración
      } else {
        setCurrentStep(3); // Dashboard
      }
    }
  }, [selectedDevice]);

  // Polling para actualizar datos en dashboard
  useEffect(() => {
    if (currentStep !== 3 || !selectedDevice) return;
    
    const interval = setInterval(() => {
      fetchDeviceStatus(selectedDevice.deviceId);
      fetchDeviceHistory(selectedDevice.deviceId);
    }, 3000);
    
    return () => clearInterval(interval);
  }, [currentStep, selectedDevice]);

  const fetchDevices = async () => {
    try {
      const response = await axios.get(`${API_URL}/api/devices`);
      setDevices(response.data);
      if (response.data.length > 0 && !selectedDevice) {
        setSelectedDevice(response.data[0]);
      } else if (response.data.length === 0) {
        setCurrentStep(1); // Paso registrar dispositivo
      }
    } catch (error) {
      console.error('Error cargando dispositivos:', error);
    }
  };

  const fetchDeviceStatus = async (deviceId) => {
    try {
      const response = await axios.get(`${API_URL}/api/status/${deviceId}`);
      setSelectedDevice(prev => ({ ...prev, currentStatus: response.data }));
    } catch (error) {
      console.error('Error cargando estado:', error);
    }
  };

  const fetchDeviceHistory = async (deviceId) => {
    try {
      const response = await axios.get(`${API_URL}/api/history/${deviceId}`);
      setHistory(response.data);
    } catch (error) {
      console.error('Error cargando historial:', error);
    }
  };

  const registerDevice = async () => {
    if (!newDeviceId) {
      setAlert({ type: 'error', message: 'Ingresa un ID para el dispositivo' });
      return;
    }
    try {
      await axios.post(`${API_URL}/api/devices/register`, {
        deviceId: newDeviceId,
        name: newDeviceName || 'Mi Tanque'
      });
      setAlert({ type: 'success', message: `✅ Dispositivo ${newDeviceId} registrado. Ahora configura tu tanque.` });
      setNewDeviceId('');
      setNewDeviceName('');
      await fetchDevices();
      setCurrentStep(2); // Pasar a configuración
      setTimeout(() => setAlert(null), 3000);
    } catch (error) {
      setAlert({ type: 'error', message: error.response?.data?.error || 'Error al registrar' });
    }
  };

  const saveConfig = async () => {
    if (!selectedDevice) return;
    
    const heightVal = parseInt(tankHeight);
    const minVal = parseInt(minLevel);
    const maxVal = parseInt(maxLevel);

    if (isNaN(heightVal) || heightVal <= 0 || heightVal > 500) {
      setAlert({ type: 'error', message: 'La altura debe ser entre 1 y 500 cm' });
      return;
    }
    if (isNaN(minVal) || minVal < 0 || minVal > 100) {
      setAlert({ type: 'error', message: 'El nivel mínimo debe ser entre 0 y 100%' });
      return;
    }
    if (isNaN(maxVal) || maxVal < 0 || maxVal > 100) {
      setAlert({ type: 'error', message: 'El nivel máximo debe ser entre 0 y 100%' });
      return;
    }
    if (minVal >= maxVal) {
      setAlert({ type: 'error', message: 'El nivel mínimo debe ser menor que el máximo' });
      return;
    }

    try {
      await axios.post(`${API_URL}/api/config`, {
        deviceId: selectedDevice.deviceId,
        minLevel: minVal,
        maxLevel: maxVal,
        tankHeight: heightVal
      });
      setAlert({ type: 'success', message: '✅ Configuración guardada. Ahora puedes ver el dashboard.' });
      setTimeout(() => setAlert(null), 3000);
      setSelectedDevice(prev => ({ ...prev, tankHeight: heightVal, minLevel: minVal, maxLevel: maxVal }));
      setCurrentStep(3); // Pasar a dashboard
    } catch (error) {
      setAlert({ type: 'error', message: 'Error al guardar configuración' });
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
        <CircularProgress size={60} />
      </Box>
    );
  }

  if (!isAuthenticated) {
    return <Auth />;
  }

  // ==================== PASO 1: REGISTRAR DISPOSITIVO ====================
  if (currentStep === 1) {
    return (
      <Container maxWidth="sm" sx={{ mt: 8 }}>
        <Card sx={{ p: 4 }}>
          <Typography variant="h4" textAlign="center" gutterBottom>
            📟 Registrar Dispositivo
          </Typography>
          <Typography variant="body2" textAlign="center" color="textSecondary" sx={{ mb: 3 }}>
            Introduce el ID del dispositivo ESP8266 (ej: ESP_PRUEBA_001)
          </Typography>
          
          {alert && <Alert severity={alert.type} sx={{ mb: 2 }} onClose={() => setAlert(null)}>{alert.message}</Alert>}
          
          <TextField
            fullWidth
            label="ID del dispositivo"
            value={newDeviceId}
            onChange={(e) => setNewDeviceId(e.target.value)}
            placeholder="Ej: ESP_PRUEBA_001"
            sx={{ mb: 2 }}
          />
          <TextField
            fullWidth
            label="Nombre (opcional)"
            value={newDeviceName}
            onChange={(e) => setNewDeviceName(e.target.value)}
            placeholder="Mi Tanque"
            sx={{ mb: 3 }}
          />
          <Button fullWidth variant="contained" size="large" onClick={registerDevice}>
            Registrar Dispositivo
          </Button>
          <Button fullWidth variant="text" onClick={logout} sx={{ mt: 2 }}>
            Cerrar Sesión
          </Button>
        </Card>
      </Container>
    );
  }

  // ==================== PASO 2: CONFIGURAR TANQUE ====================
  if (currentStep === 2 && selectedDevice) {
    return (
      <Container maxWidth="md" sx={{ mt: 4 }}>
        <Card sx={{ p: 4 }}>
          <Typography variant="h4" textAlign="center" gutterBottom>
            ⚙️ Configura tu Tanque
          </Typography>
          <Typography variant="body2" textAlign="center" color="textSecondary" sx={{ mb: 3 }}>
            Dispositivo: {selectedDevice.name || selectedDevice.deviceId}
          </Typography>
          
          {alert && <Alert severity={alert.type} sx={{ mb: 2 }} onClose={() => setAlert(null)}>{alert.message}</Alert>}
          
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography gutterBottom>📏 Altura del Tanque (cm)</Typography>
              <TextField
                fullWidth
                type="number"
                value={tankHeight}
                onChange={(e) => setTankHeight(e.target.value)}
                placeholder="Ej: 100"
                InputProps={{ endAdornment: <InputAdornment position="end">cm</InputAdornment> }}
              />
            </Grid>
            
            <Grid item xs={12}>
              <Typography gutterBottom>⬇️ Nivel Mínimo (Encender bomba)</Typography>
              <TextField
                fullWidth
                type="number"
                value={minLevel}
                onChange={(e) => setMinLevel(e.target.value)}
                placeholder="Ej: 20"
                InputProps={{ endAdornment: <InputAdornment position="end">%</InputAdornment> }}
              />
              <Slider
                value={parseInt(minLevel) || 0}
                onChange={(_, val) => setMinLevel(val.toString())}
                min={0}
                max={100}
                valueLabelDisplay="auto"
                color="warning"
                sx={{ mt: 2 }}
              />
            </Grid>
            
            <Grid item xs={12}>
              <Typography gutterBottom>⬆️ Nivel Máximo (Apagar bomba)</Typography>
              <TextField
                fullWidth
                type="number"
                value={maxLevel}
                onChange={(e) => setMaxLevel(e.target.value)}
                placeholder="Ej: 80"
                InputProps={{ endAdornment: <InputAdornment position="end">%</InputAdornment> }}
              />
              <Slider
                value={parseInt(maxLevel) || 0}
                onChange={(_, val) => setMaxLevel(val.toString())}
                min={0}
                max={100}
                valueLabelDisplay="auto"
                color="primary"
                sx={{ mt: 2 }}
              />
            </Grid>
          </Grid>
          
          <Button fullWidth variant="contained" size="large" onClick={saveConfig} sx={{ mt: 3 }}>
            Guardar y ver Dashboard
          </Button>
          <Button fullWidth variant="text" onClick={logout} sx={{ mt: 2 }}>
            Cerrar Sesión
          </Button>
        </Card>
      </Container>
    );
  }

  // ==================== PASO 3: DASHBOARD ====================
  if (!selectedDevice) {
    return (
      <Container maxWidth="sm" sx={{ mt: 8 }}>
        <Card sx={{ p: 4, textAlign: 'center' }}>
          <Typography variant="h5">No hay dispositivos</Typography>
          <Button variant="contained" onClick={() => setCurrentStep(1)} sx={{ mt: 2 }}>
            Registrar Dispositivo
          </Button>
        </Card>
      </Container>
    );
  }

  const levelPercentage = selectedDevice?.currentStatus?.level || 0;
  const pumpStatus = selectedDevice?.currentStatus?.pumpStatus || false;
  const currentMin = selectedDevice?.minLevel || 20;
  const currentMax = selectedDevice?.maxLevel || 80;

  const chartData = history.slice(-20).map(item => ({
    time: new Date(item.timestamp).toLocaleTimeString(),
    level: item.level
  }));

  const avgLevel = history.length ? (history.reduce((sum, h) => sum + h.level, 0) / history.length).toFixed(0) : 0;

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: COLORS.light, p: 3 }}>
      {/* Header */}
      <Box sx={{ mb: 4, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <Typography variant="h4" fontWeight="bold">
          💧 Control de Tanque
        </Typography>
        <Box display="flex" gap={1} alignItems="center">
          <Chip label={user?.username} size="small" />
          <Button variant="outlined" size="small" onClick={logout}>Salir</Button>
        </Box>
      </Box>

      {alert && <Alert severity={alert.type} sx={{ mb: 2 }} onClose={() => setAlert(null)}>{alert.message}</Alert>}

      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <Card sx={{ p: 3 }}>
            <Typography variant="subtitle2" color="textSecondary" gutterBottom>
              📊 Nivel Actual - {selectedDevice.name}
            </Typography>
            <Typography variant="h2" fontWeight="bold" color={COLORS.primary} sx={{ my: 2 }}>
              {Math.round(levelPercentage)} %
            </Typography>
            <LinearProgress variant="determinate" value={levelPercentage} sx={{ height: 12, borderRadius: 6, mb: 2 }} />
            <Box display="flex" justifyContent="space-between">
              <Typography variant="caption">Mín: {currentMin}%</Typography>
              <Typography variant="caption">Máx: {currentMax}%</Typography>
            </Box>
          </Card>
        </Grid>

        <Grid item xs={12} md={6}>
          <Card sx={{ p: 3 }}>
            <Typography variant="subtitle2" color="textSecondary" gutterBottom>
              🔌 Estado de la Bomba
            </Typography>
            <Typography variant="h3" fontWeight="bold" color={pumpStatus ? COLORS.success : COLORS.danger}>
              {pumpStatus ? 'ENCENDIDA' : 'APAGADA'}
            </Typography>
            <Typography variant="body2" color="textSecondary" sx={{ mt: 1 }}>
              {pumpStatus 
                ? 'La bomba está funcionando. El nivel está por debajo del mínimo.'
                : 'La bomba está detenida. El nivel está dentro del rango configurado.'}
            </Typography>
          </Card>
        </Grid>

        <Grid item xs={12}>
          <Card sx={{ p: 3 }}>
            <Typography variant="subtitle2" color="textSecondary" gutterBottom>
              📈 Estadísticas del Día
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={4}>
                <Box textAlign="center">
                  <Typography variant="h4" fontWeight="bold" color={COLORS.primary}>
                    {avgLevel}%
                  </Typography>
                  <Typography variant="caption">Promedio</Typography>
                </Box>
              </Grid>
              <Grid item xs={4}>
                <Box textAlign="center">
                  <Typography variant="h4" fontWeight="bold" color={COLORS.danger}>
                    {history.length > 0 ? Math.max(...history.map(h => h.level)) : 0}%
                  </Typography>
                  <Typography variant="caption">Máximo</Typography>
                </Box>
              </Grid>
              <Grid item xs={4}>
                <Box textAlign="center">
                  <Typography variant="h4" fontWeight="bold" color={COLORS.warning}>
                    {history.length > 0 ? Math.min(...history.map(h => h.level)) : 0}%
                  </Typography>
                  <Typography variant="caption">Mínimo</Typography>
                </Box>
              </Grid>
            </Grid>
          </Card>
        </Grid>

        <Grid item xs={12}>
          <Card sx={{ p: 3 }}>
            <Typography variant="subtitle2" color="textSecondary" gutterBottom>
              📊 Historial de Nivel
            </Typography>
            {history.length > 0 ? (
              <ResponsiveContainer width="100%" height={300}>
                <AreaChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="time" tick={{ fontSize: 10 }} />
                  <YAxis domain={[0, 100]} unit="%" />
                  <RechartsTooltip formatter={(value) => `${Math.round(value)}%`} />
                  <Area type="monotone" dataKey="level" stroke={COLORS.primary} fill={COLORS.primary} fillOpacity={0.3} />
                </AreaChart>
              </ResponsiveContainer>
            ) : (
              <Typography variant="body2" color="textSecondary" textAlign="center" py={4}>
                Sin datos aún. Conecta tu ESP8266 para empezar a recibir lecturas.
              </Typography>
            )}
          </Card>
        </Grid>
      </Grid>

      <Box textAlign="center" mt={3}>
        <Button variant="outlined" onClick={() => setCurrentStep(2)}>
          ⚙️ Modificar Configuración
        </Button>
      </Box>
    </Box>
  );
}

export default App;